import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Búsqueda de Texto Completo","description":"","frontmatter":{},"headers":[],"relativePath":"es/advanced/search.md","filePath":"es/advanced/search.md","lastUpdated":1784903584000}'),n={name:"es/advanced/search.md"};function d(i,e,c,r,p,l){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="busqueda-de-texto-completo" tabindex="-1">Búsqueda de Texto Completo <a class="header-anchor" href="#busqueda-de-texto-completo" aria-label="Permalink to &quot;Búsqueda de Texto Completo&quot;">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripción General <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to &quot;Descripción General&quot;">​</a></h2><p>swag2mcp incluye un motor de búsqueda de texto completo incorporado (bluge) que indexa todos los endpoints de todas las especificaciones. El LLM puede buscar endpoints por método, ruta, resumen o etiqueta — incluso sin conocer el ID del endpoint.</p><h2 id="como-funciona-la-indexacion" tabindex="-1">Cómo funciona la indexación <a class="header-anchor" href="#como-funciona-la-indexacion" aria-label="Permalink to &quot;Cómo funciona la indexación&quot;">​</a></h2><p>Cuando se agrega o actualiza una especificación, cada endpoint se indexa. Los siguientes campos se pueden buscar:</p><table tabindex="0"><thead><tr><th>Campo</th><th>Descripción</th><th>Ejemplo</th></tr></thead><tbody><tr><td><code>method</code></td><td>Método HTTP</td><td><code>GET</code>, <code>POST</code>, <code>PUT</code></td></tr><tr><td><code>path</code></td><td>Ruta del endpoint de API</td><td><code>/api/v1/users/{id}</code></td></tr><tr><td><code>summary</code></td><td>Resumen de OpenAPI</td><td>&quot;Find pet by ID&quot;</td></tr><tr><td><code>tag</code></td><td>Categoría del endpoint</td><td>&quot;pets&quot;, &quot;users&quot;</td></tr><tr><td><code>_all</code></td><td>Todos los campos combinados</td><td>method + path + tag + summary</td></tr></tbody></table><p>El índice se reconstruye en cada inicio del servidor MCP. Se almacena en memoria para búsquedas rápidas.</p><h2 id="sintaxis-de-consulta" tabindex="-1">Sintaxis de consulta <a class="header-anchor" href="#sintaxis-de-consulta" aria-label="Permalink to &quot;Sintaxis de consulta&quot;">​</a></h2><p>La búsqueda admite una sintaxis de consulta enriquecida para un filtrado preciso:</p><table tabindex="0"><thead><tr><th>Ejemplo</th><th>Descripción</th></tr></thead><tbody><tr><td><code>pet</code></td><td>Búsqueda de texto simple en todos los campos</td></tr><tr><td><code>method:GET</code></td><td>Encontrar todos los endpoints GET</td></tr><tr><td><code>tag:pets</code></td><td>Encontrar endpoints en la etiqueta &quot;pets&quot;</td></tr><tr><td><code>path:&quot;/api/v1/users&quot;</code></td><td>Coincidencia exacta de ruta</td></tr><tr><td><code>+method:POST +tag:pet</code></td><td>Debe coincidir con ambas condiciones</td></tr><tr><td><code>-method:DELETE</code></td><td>Excluir métodos DELETE</td></tr><tr><td><code>create~</code></td><td>Búsqueda difusa (tolerante a errores tipográficos)</td></tr><tr><td><code>cr*</code></td><td>Búsqueda con comodín</td></tr><tr><td><code>&quot;find pet&quot;</code></td><td>Búsqueda de frase</td></tr><tr><td><code>+summary:pet -method:DELETE</code></td><td>Incluir &quot;pet&quot; en resumen, excluir DELETE</td></tr></tbody></table><h3 id="busqueda-por-campo-especifico" tabindex="-1">Búsqueda por campo específico <a class="header-anchor" href="#busqueda-por-campo-especifico" aria-label="Permalink to &quot;Búsqueda por campo específico&quot;">​</a></h3><p>Puede buscar dentro de campos específicos usando la sintaxis <code>field:value</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>method:GET</span></span>
<span class="line"><span>tag:pets</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span>summary:&quot;find pet by status&quot;</span></span></code></pre></div><h3 id="operadores-booleanos" tabindex="-1">Operadores booleanos <a class="header-anchor" href="#operadores-booleanos" aria-label="Permalink to &quot;Operadores booleanos&quot;">​</a></h3><ul><li><code>+</code> — el término debe coincidir (AND)</li><li><code>-</code> — el término no debe coincidir (NOT)</li><li>Espacio entre términos — OR (cualquier término puede coincidir)</li></ul><h3 id="busqueda-difusa-y-comodines" tabindex="-1">Búsqueda difusa y comodines <a class="header-anchor" href="#busqueda-difusa-y-comodines" aria-label="Permalink to &quot;Búsqueda difusa y comodines&quot;">​</a></h3><ul><li><code>term~</code> — búsqueda difusa (coincide con palabras similares, maneja errores tipográficos)</li><li><code>te*</code> — comodín (coincide con cualquier carácter)</li><li><code>te?t</code> — comodín de un solo carácter</li></ul><h2 id="ejemplos" tabindex="-1">Ejemplos <a class="header-anchor" href="#ejemplos" aria-label="Permalink to &quot;Ejemplos&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Encontrar todas las solicitudes GET</span></span>
<span class="line"><span>method:GET</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Encontrar solicitudes POST en la etiqueta pet</span></span>
<span class="line"><span>+method:POST +tag:pet</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Encontrar endpoints por ruta exacta</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Encontrar por descripción</span></span>
<span class="line"><span>&quot;find pet by status&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Encontrar todo excepto DELETE</span></span>
<span class="line"><span>+summary:pet -method:DELETE</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Búsqueda difusa para &quot;create&quot; (maneja errores tipográficos)</span></span>
<span class="line"><span>create~</span></span></code></pre></div><h2 id="herramienta-mcp" tabindex="-1">Herramienta MCP <a class="header-anchor" href="#herramienta-mcp" aria-label="Permalink to &quot;Herramienta MCP&quot;">​</a></h2><p>La herramienta MCP <code>search</code> expone el motor de búsqueda al LLM:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ search(query: &quot;find pet by status&quot;, limit: 5)</span></span>
<span class="line"><span>← GET /pet/findByStatus — Finds Pets by status</span></span>
<span class="line"><span>   GET /pet/{petId} — Find pet by ID</span></span></code></pre></div><h3 id="parametros" tabindex="-1">Parámetros <a class="header-anchor" href="#parametros" aria-label="Permalink to &quot;Parámetros&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parámetro</th><th>Requerido</th><th>Descripción</th></tr></thead><tbody><tr><td><code>query</code></td><td>Sí</td><td>Consulta de búsqueda (admite sintaxis estructurada)</td></tr><tr><td><code>limit</code></td><td>Sí</td><td>Resultados máximos (1-50)</td></tr></tbody></table><h2 id="notas-importantes" tabindex="-1">Notas importantes <a class="header-anchor" href="#notas-importantes" aria-label="Permalink to &quot;Notas importantes&quot;">​</a></h2><ul><li><strong>El índice está en memoria</strong> — se reconstruye cada vez que se inicia el servidor MCP. No hay un archivo de índice persistente.</li><li><strong>Todos los campos están en minúsculas</strong> — las búsquedas no distinguen entre mayúsculas y minúsculas</li><li><strong>El límite máximo es 50</strong> — no puede solicitar más de 50 resultados</li><li><strong>La sintaxis de consulta inválida</strong> devuelve un mensaje de error útil con ejemplos</li><li><strong>El campo <code>_all</code></strong> combina method, path, tag y summary para búsquedas de texto simples</li></ul>`,26)])])}const h=a(n,[["render",d]]);export{m as __pageData,h as default};
